ALTER TABLE coord_receipts ADD COLUMN project_id TEXT;
UPDATE coord_receipts SET project_id=COALESCE(json_extract(result_json,'$.projectId'),(SELECT project_id FROM coord_leases WHERE workspace_id=coord_receipts.workspace_id AND issue_id=COALESCE(json_extract(result_json,'$.issueId'),json_extract(result_json,'$[0].leaseIssueId'))));
ALTER TABLE coord_file_claims ADD COLUMN project_id TEXT;
UPDATE coord_file_claims SET project_id=(SELECT project_id FROM coord_leases WHERE workspace_id=coord_file_claims.workspace_id AND issue_id=lease_issue_id);
ALTER TABLE coord_reports ADD COLUMN project_id TEXT;
UPDATE coord_reports SET project_id=(SELECT project_id FROM coord_leases WHERE workspace_id=coord_reports.workspace_id AND issue_id=coord_reports.issue_id);
ALTER TABLE coord_report_history ADD COLUMN project_id TEXT;
UPDATE coord_report_history SET project_id=(SELECT project_id FROM coord_leases WHERE workspace_id=coord_report_history.workspace_id AND issue_id=coord_report_history.issue_id);
UPDATE coord_events SET project_id=(SELECT project_id FROM coord_leases WHERE workspace_id=coord_events.workspace_id AND issue_id=coord_events.issue_id) WHERE project_id IS NULL AND issue_id IS NOT NULL;
CREATE TABLE coord_frozen_scopes (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging','purged')), PRIMARY KEY(workspace_id,project_id));
CREATE TABLE coord_purge_bypass (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(workspace_id,project_id));
CREATE TRIGGER coord_freeze_file_claims_insert BEFORE INSERT ON coord_file_claims WHEN EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER coord_freeze_file_claims_update BEFORE UPDATE ON coord_file_claims WHEN (EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id))) OR (EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=OLD.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=OLD.project_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
